import copy
import json
import os
import re
import shutil
import subprocess
import sys
from builtins import str
from os import listdir
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass
from taf.ul.trs_e2e_fw.lib.oam.admin.counters.datetime_operations import DatetimeOperations
from taf.ul.trs_e2e_fw.lib.oam.admin.counters.find import Find
from taf.ul.trs_e2e_fw.lib.oam.admin.counters.xml_parser import XmlParser
