from taf.ul.trs_e2e_fw.lib.utils.unzip import uncompress
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler

logger = BackgroundLogger.Instance()


class Counters(AdminBaseClass):
    """Counters"""
    initial_values = None

    def __init__(self):
        super(Counters, self).__init__()
        self.datetime_ops = DatetimeOperations()
        self.parser_obj = XmlParser()
        self.find_obj = Find()
        self.config = ConfigHandler.get_config()

    def _get_json_file_content(self, analysis_file):
        counters_analysis_dict = {}
        counters_analysis_files = [os.path.join(self.config['common_resources_path'],
                                                analysis_file),
                                   os.path.join(self.config['feature_resources_path'],
                                                analysis_file)]
        for counters_analysis_file in counters_analysis_files:
            if os.path.exists(counters_analysis_file):
                with open(counters_analysis_file, "r") as file_handle:
                    counters_analysis_dict.update(json.load(file_handle))
        return counters_analysis_dict

    @check_rat
    def pm_counters_start(self, **kwargs):
        """
        Collects counters from the latest PM file
        :param analysis: Analysis name from the counters_analysis.json
        :param pm_interval : waits for this much time for pm files to get generated
        :param alias: Name of execution context
        :return: None
        """
        analysis = kwargs.pop("analysis")
        counter_analysis_file = kwargs.pop("counter_analysis_file")
        pm_interval = kwargs.pop("pm_interval", '15')
        alias = kwargs.pop("alias", 'default')
        dut = global_vars.alias_dut_dict[alias]
        logger.debug("wait for next interals...")
        current_time = self.datetime_ops.get_currenttime_on_enb(dut)
        self.datetime_ops.wait_for_next_interval(current_time=current_time, interval=pm_interval,
                                                 additional_wait_time=110)
        logger.debug("getting initial values...")
        Counters.initial_values = self._get_analysis_structure_filled_with_actuals(analysis=analysis,
                                                                                   counter_analysis_file=counter_analysis_file,
                                                                                   alias=alias)
        logger.debug("Initial values obtained ...\n{}".format(Counters.initial_values))
        logger.debug("getting current time on enb ...")
        self.datetime_ops.get_currenttime_on_enb(dut)
        for distname, dist_value in list(Counters.initial_values["counters"][analysis].items()):
            for counter, counter_params in list(dist_value.items()):
                counter_val = Counters.initial_values["counters"][analysis][distname][counter]["value"]
                if counter_val is None:
                    raise Exception("Counter {} is Not Present".format(counter))
        logger.debug("First Interval Counters \n{}".format(Counters.initial_values))

    @check_rat
    def verify_pm_counters(self, **kwargs):
        """
        Collects counters from the latest PM file
        :param analysis: Analysis name from the counters_analysis.json
        :param pm_interval : waits for this much time for pm files to get generated
        :param alias: Name of execution context
        :return: None
        """
        analysis = kwargs.pop("analysis")
        counter_analysis_file = kwargs.pop("counter_analysis_file")
        pm_interval = kwargs.pop("pm_interval", '15')
        alias = kwargs.pop("alias", 'default')
        dut = global_vars.alias_dut_dict[alias]
        current_time = self.datetime_ops.get_currenttime_on_enb(dut)
        # self.datetime_ops.wait_for_next_interval(current_time, pm_interval, global_vars.alias_dut_dict[alias],
        #                                          additional_wait_time=110)
        self.datetime_ops.wait_for_next_interval(current_time=current_time, interval=pm_interval,
                                                 additional_wait_time=110)
        error_flag = True
        logger.debug(self.datetime_ops.get_currenttime_on_enb(dut))
        logger.info("Getting Counters From Second Interval....")
        final_value = self._get_analysis_structure_filled_with_actuals(analysis, counter_analysis_file, alias=alias)
        # logger.debug("Second Interval Counters \n{}".format(final_value))
        for distname, dist_value in list(final_value["counters"][analysis].items()):
            for counter, counter_value in list(dist_value.items()):
                logger.debug("Distname:: {} ## Counter:: {} ## Counter Value:: {} ".format(distname, counter,
                                                                                        counter_value["value"]))
                if counter_value["value"] is not None and \
                        Counters.initial_values["counters"][analysis][distname][counter]["value"] \
                        is not None:
                    logger.debug("Initial counter value of counter {} is  {}".format(counter, Counters.initial_values[
                        "counters"][analysis][distname][counter]["value"]))
                    error_flag = self._get_result(analysis, counter, counter_value, distname,
                                                  error_flag)
                else:
                    error_flag = False
                    counter_value["result"] = "Failed - Counter not found"

        json_filename = 'execution_logs/{}_{}_counters.json'.format(
            analysis, config_utils.get_config_variable(["bts_id"]))
        logger.debug("Json file name :: {}".format(json_filename))
        if not os.path.exists(os.path.dirname(json_filename)):
            os.makedirs(os.path.dirname(json_filename))
        logger.debug("writing to json file... ")
        self._write_to_json_file(final_value["counters"][analysis], json_filename)
        if not error_flag:
            logger.debug(final_value["counters"][analysis])
            raise PMCountersValidationError(
                "Atleast one counter validation failed, refer to counter analysis summary file "
                "{}".format(json_filename))
        return final_value["counters"][analysis]

    def _get_result(self, analysis, counter, counter_value, distname, error_flag):
        if counter_value["analysis_type"].lower() == "diff":
            output = int(counter_value["value"]) - int(
                Counters.initial_values["counters"][analysis][distname][counter]["value"])
        elif counter_value["analysis_type"].lower() == "current":
            output = int(counter_value["value"])
        lower_bound, upper_bound = self._convert_range(counter_value["expected_value"])
        lower_bound = int(int(lower_bound) - (float(counter_value["tolerance"]) / 100.0 *
                                              int(lower_bound)))
        if not upper_bound == sys.maxsize:
            upper_bound = int(int(upper_bound) + (float(counter_value["tolerance"]) / 100.0 *
                                                  int(upper_bound)))
        logger.debug('lower bound: {} upper bound: {}'.format(str(lower_bound), str(upper_bound)))
        logger.debug('expected val: {} output val: {}'.format(counter_value["expected_value"],
                                                              str(output)))
        if (int(lower_bound) <= output <= int(upper_bound)) \
                or counter_value["expected_value"] == counter_value["value"]:
            counter_value["result"] = "Pass"
            counter_value["output_val"] = output
            counter_value["final_counter_value"] = counter_value["value"]
        else:
            counter_value["result"] = "Failed - Evaluation Failed"
            counter_value["output_val"] = output
            counter_value["final_counter_value"] = counter_value["value"]
            error_flag = False
        return error_flag

    def _convert_range(self, range_value):
        list_split = list(re.split(r'\.\.', range_value))
        if len(list_split) == 2:
            if list_split[0].strip() == '*':
                lower_bound = -sys.maxsize - 1  # -2147483648
            else:
                lower_bound = int(list_split[0])
            if list_split[1].strip() == '*':
                upper_bound = sys.maxsize
            else:
                upper_bound = int(list_split[1])
        elif len(list_split) == 1:
            upper_bound = lower_bound = int(list_split[0])
        else:
            return 0

        return lower_bound, upper_bound

    def _write_to_file(self, file_content, pm_file):
        file_without_extension = os.path.splitext(pm_file)[0]
        target_file = open(file_without_extension, 'w')
        target_file.write(file_content)
        target_file.close()
        return file_without_extension

    def _get_analysis_structure_filled_with_actuals(self, analysis, counter_analysis_file, alias):
        target_zip_file = 'pm_files.zip'
        self.factory.admin.collect_pm_files(target_zip_file, connection=alias)
        if not os.path:
            raise Exception("No PM Files retrieved from admin")
        latest_pm_file = self._get_latest_pm_file(target_zip_file)
        logger.info("latest_pm_file :{}".format(latest_pm_file))
        self.copy_to_execution_logs(latest_pm_file)
        all_intervals_mocs_content = self.parser_obj.parse_and_return_dict(latest_pm_file)
        # logger.debug("all_intervals_mocs_content : \n{}".format(str(all_intervals_mocs_content)))
        counters_ref = self._get_json_file_content(counter_analysis_file)
        logger.debug("counters_ref before expanding")
        logger.debug('{}'.format(str(counters_ref["counters"][analysis])))
        counters_ref["counters"][analysis] = self._expand_counters_analysis(
            all_intervals_mocs_content, analysis, counters_ref)
        logger.debug("counters_ref after expanding")
        logger.debug('{}'.format(str(counters_ref["counters"][analysis])))
        for distname, dist_value in list(counters_ref["counters"][analysis].items()):
            for counter_name, c_value in list(dist_value.items()):
                counter_value = self.find_obj.\
                    find_and_return_counter_value_from_latest_interval(all_intervals_mocs_content,
                                                                       distname, counter_name)
                counters_ref["counters"][analysis][distname][counter_name]["value"] = counter_value
        logger.debug('counters_ref:: {}'.format(str(counters_ref["counters"][analysis])))
        return counters_ref

    def _expand_counters_analysis(self, all_intervals_mocs_content, analysis, counters_ref):
        new_moc_dict = {}
        all_intervals_mocs_content = json.dumps(all_intervals_mocs_content)
        counters_profile_params = get_config_variable(dict_path_list=['counters', analysis],
                                                      dict_source=counters_ref)
        # for distname, dist_value in counters_ref["counters"][analysis].iteritems():
        for distname, dist_value in list(counters_profile_params.items()):
            logger.debug("distname with regex: {}".format(distname))
            distname_regx = replace_builtinvars(distname)
            logger.debug("formatted distname:{}".format(distname_regx))
            distname = re.compile(distname_regx)
            list_of_mocs = re.findall(distname, all_intervals_mocs_content)
            logger.debug("list of matched mocs: {}".format(str(list_of_mocs)))
            if len(list_of_mocs):
                for moc in set(list_of_mocs):
                    temp_dist = copy.deepcopy(dist_value)
                    new_moc_dict[moc] = temp_dist
                    del temp_dist
            else:
                raise Exception("No moc matched the regular expression {}".format(distname_regx))

        return new_moc_dict

    def copy_to_execution_logs(self, latest_pm_file):
        """
        Function to copy execution log
        """
        pm_file = 'execution_logs/'
        if not os.path.exists(os.path.dirname(pm_file)):
            os.makedirs(os.path.dirname(pm_file))
        subprocess.check_output("cp {} {}".format(latest_pm_file, pm_file), shell=True)

    def _get_latest_pm_file(self, pm_zip_fle):
        latest_pm_file = ''
        dest_dir = 'tmp'
        if os.path.exists(dest_dir):
            shutil.rmtree(dest_dir)
        uncompress(pm_zip_fle, dest_dir)
        dest_dir = 'tmp/PERFMON_FILES'
        dt_obj1 = self.datetime_ops.get_oldest_datetime()  # Only for initial comparison purpose
        for pm_file in listdir(dest_dir):
            logger.info("PM File: {}".format(pm_file))
            dt_obj2 = self.datetime_ops.get_datetime_from_filename(pm_file)
            if dt_obj2 >= dt_obj1:
                if dt_obj1 == dt_obj2:
                    if 'raw' in pm_file:
                        latest_pm_file = pm_file
                else:
                    latest_pm_file = pm_file
                    dt_obj1 = dt_obj2
        return os.path.join(dest_dir, latest_pm_file)

    def _write_to_json_file(self, final_value, json_filename):
        with open(json_filename, 'w') as j_file:
            json.dump(final_value, j_file)
